#pragma once
#include <string>
#include "gpu/shaders.h"

namespace gpu {

// Translates HLSL generated by gpu/shaders.cpp into Apple Metal Shading Language (MSL).
// Vertex entry point is always `vs_main`, fragment entry point is always `fs_main`.
// Constant buffers bind at [[buffer(16)]] (VC: float4 c[192]) and [[buffer(17)]] (DC: DrawConstants).
std::string TranslateVertexHlslToMsl(const std::string& hlsl, uint16_t regs);
std::string TranslatePixelHlslToMsl(const std::string& hlsl, const PixelKey& key);

}  // namespace gpu
